('66caaa959fc45fcc95ea3d7c03efc8b8', 'en', $t$Solar equipment on the wooden wall: charge controller, battery and fuse box$t$),
('87e48057e34a2ceceb22d53fa737d43d', 'en', $t$View through an old timber door into the storeroom with boxes and a chest of drawers$t$),
('bca647d8568bf7a4e2f85fe52bb75773', 'en', $t$Hut on open pasture seen from above, rocky mountains and wooded slopes behind$t$),
('cefc05e41b432821d5d971ca372ce02d', 'en', $t$Winter view from the hut over snowy slopes and fir trees to snow-capped peaks$t$),
('f0858891400caa04475042de695bb2a8', 'en', $t$Slope deep in snow with a large deciduous tree, clouds over the mountains$t$),
